"""final_evaluation spine: serial play of final checkpoints and both baselines on FINAL_SEEDS.

`compare_baselines` and `verdict` are thickened by their own tasks, so these tests replace them
(and the other steps' stubs) with recording doubles.
"""

import importlib.util
import json
import sys
from collections import Counter
from collections.abc import Mapping, Sequence
from dataclasses import dataclass, replace
from pathlib import Path
from typing import Any, Literal

import numpy as np
import pytest

from rllab.core import (
    FINAL_SEEDS,
    ActionSpace,
    Array,
    Direction,
    Episode,
    EpisodeResult,
    Policy,
    TeamSpec,
    World,
    WorldSpec,
)
from rllab.evaluate import Comparison, Summary, Verdict
from rllab.evaluate.final import play, summary
from rllab.runlog import Checkpoint, EvalPoint, Run

CONTRACTS = Path(__file__).parents[2] / "contracts"
RUN_SCORES = {
    "snake-s1": 11.0,
    "snake-s2": 12.0,
    "snake-s3": 13.0,
    "snake-s4": 14.0,
    "snake-s5": 15.0,
}
RANDOM_SCORE = 1.0
RULE_SCORE = 8.0
Baseline = Literal["random", "rule"]


def load_kit() -> Any:
    if "contracts_kit" not in sys.modules:
        spec = importlib.util.spec_from_file_location("contracts_kit", CONTRACTS / "kit.py")
        assert spec is not None
        assert spec.loader is not None
        module = importlib.util.module_from_spec(spec)
        sys.modules["contracts_kit"] = module
        spec.loader.exec_module(module)
    return sys.modules["contracts_kit"]


@dataclass(frozen=True)
class Scripted:
    """A policy double whose episodes score `score` for its team; `kind` names what made it."""

    kind: str
    score: float

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        return np.zeros(len(obs), dtype=np.int64)


@dataclass(frozen=True)
class FakeWorld:
    spec: WorldSpec


@dataclass
class Played:
    """Every episode's seed and policy kind per team, and every compare_baselines call."""

    episodes: list[tuple[int, dict[str, str]]]
    compared: list[tuple[str, Array, Mapping[Baseline, Array]]]


@pytest.fixture
def kit() -> Any:
    return load_kit()


@pytest.fixture
def runs(kit: Any, tmp_path: Path) -> list[Run]:
    found: list[Run] = kit.fake("runlog.find_runs")(tmp_path, "snake", "default")
    return found


def load_policy(ckpt: Checkpoint, team: str, spec: WorldSpec) -> Policy:
    return Scripted(f"learned:{ckpt.run}:{ckpt.pct}", RUN_SCORES[ckpt.run])


def random_policy(action: ActionSpace) -> Policy:
    return Scripted("random", RANDOM_SCORE)


def rule_for(world: str, variant: str, team: str) -> Policy:
    return Scripted("rule", RULE_SCORE)
